    state.codxJuniorWidth = width
    $storex.ui.saveState()
  },
  toggleLogs(state) {
    state.showLogs = !state.showLogs
    $storex.ui.showApp({
      name: 'Logs',
      component: 'log-viewer'
    })
  },
  openChatLogs(state) {
    state.showLogs = !state.showLogs
    $storex.ui.showApp({
      name: 'Chat logs',
