      $storex.ui.showApp({
        key: 'vibe-coding',
        name: 'Vibe Coding',
        component: 'vibe-coding',
        params: {}
      })
    },

    openProjects() {
      if ($storex.ui.isDesktopMode) {
        $storex.ui.showApp({
          key: 'projects',
          name: 'Projects',
          component: 'projects',
          params: {}
        })
      } else {
        $storex.$router.push({ path: '/projects' })
      }
    },

    openTeams() {
      if ($storex.ui.isDesktopMode) {
        $storex.ui.showApp({
          key: 'teams',
          name: 'Teams',
          component: 'teams',
          params: {}
        })
      } else {
        $storex.ui.setActiveTab('team')
      }
    },

    openWorkspaces() {
      if ($storex.ui.isDesktopMode) {
        $storex.ui.showApp({
          key: 'workspaces',
          name: 'Workspaces',
          component: 'workspaces',
          params: {}
        })
      } else {
        $storex.$router.push(routes.workspace.list())
      }
    },

    openWorkspace(_, workspace) {
      if (!workspace || !workspace.key) {
        console.warn('[UI] openWorkspace: invalid workspace', workspace)
        return
      }

      const workspaceId = workspace.key
      const workspaceName = workspace.name || `workspace-${workspaceId}`

      if ($storex.ui.isDesktopMode) {
        $storex.ui.showApp({
          tabId: `workspace-${workspaceId}`,
          name: workspaceName,
          component: 'workspace',
          ...workspace
        })
      } else {
        $storex.$router.$navigation.workspaces.open(workspaceId, workspaceName)
      }
    },

    openTasks() {
      if ($storex.ui.isDesktopMode) {
        $storex.ui.showApp({
          key: 'tasks',
